import{_ as t,o,c as s,a6 as r}from"./chunks/framework.O8w_gp-L.js";const m=JSON.parse('{"title":"Loomhaven: your home base","description":"","frontmatter":{},"headers":[],"relativePath":"guides/loomhaven.md","filePath":"guides/loomhaven.md"}'),a={name:"guides/loomhaven.md"};function n(i,e,l,g,h,d){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="loomhaven-your-home-base" tabindex="-1">Loomhaven: your home base <a class="header-anchor" href="#loomhaven-your-home-base" aria-label="Permalink to &quot;Loomhaven: your home base&quot;">​</a></h1><p>Loomhaven&#39;s bridge is lined with stands. Walk up and press <strong>Z</strong> (<strong>G</strong> on WASD). <strong>More → Go to</strong> walks you to any stand.</p><p><strong>The Stage Gate</strong> opens the chapter map. Every stage starts here.</p><h2 id="what-opens-when" tabindex="-1">What opens when <a class="header-anchor" href="#what-opens-when" aria-label="Permalink to &quot;What opens when&quot;">​</a></h2><ul><li><strong>After 1-1:</strong> Forge</li><li><strong>After 1-2:</strong> Social and Party, Drill post</li><li><strong>After 1-3:</strong> Storage, Style</li><li><strong>After 1-4:</strong> Fishing</li><li><strong>After 1-5:</strong> Gathering Hall, Hard mode, the forge&#39;s next tier</li><li><strong>After 2-1:</strong> Cookery, Daily challenge</li><li><strong>After 2-2:</strong> Bounty Board</li><li><strong>After 2-3:</strong> Rooftop Run, brewing at the Cookery</li><li><strong>After 2-4:</strong> Leaderboards</li><li><strong>After 2-5:</strong> Weekly goals A locked stand says which stage opens it.</li></ul><h2 id="the-stands" tabindex="-1">The stands <a class="header-anchor" href="#the-stands" aria-label="Permalink to &quot;The stands&quot;">​</a></h2><ul><li><strong>Storage:</strong> Tilda keeps items, gear and silver for all your fighters.</li><li><strong>Fishing:</strong> cast into the canal and hold <strong>Reel</strong>. Don&#39;t snap the line!</li><li><strong>Cookery:</strong> cook fish into dishes that help for one stage.</li><li><strong>Supplies:</strong> Tibble buys and sells the basics.</li><li><strong>Brewing</strong> (at the Cookery): turn Meadowmint into Field Dressings.</li><li><strong>Gathering Hall:</strong> pick ore, timber, flax and herbs.</li><li><strong>Bounty Board:</strong> three short hunts a day.</li><li><strong>Creature notes:</strong> in the Quests window.</li><li><strong>Drill post:</strong> practise moves and boss attacks.</li><li><strong>Rooftop Run:</strong> race across the roofs.</li><li><strong>Leaderboards:</strong> fastest clears and biggest combos.</li><li><strong>The Sampler:</strong> each stage&#39;s top names.</li><li><strong>Mail:</strong> notes and gifts from the Fraybound team.</li><li><strong>Daily Gift:</strong> come back each day. Never locked.</li><li><strong>Hall of Memories:</strong> eight champion shrines.</li><li><strong>Relive the memory:</strong> replay a champion&#39;s stages.</li></ul><p><strong>The Long Table</strong> 🍂 (November 23-29): a harvest feast. There is a plate for you in the Daily Gift.</p><p><strong>Opens in a later update:</strong> the Weighhouse, the Errand Board, the Lamplighter&#39;s Fund, Vigil Road and the Wick Trial.</p>',9)])])}const c=t(a,[["render",n]]);export{m as __pageData,c as default};
